using SampleRack.SharedKernel.Abstractions;
using SampleRack.SharedKernel.Exceptions;
using SampleRack.SharedKernel.ValueObjects;

namespace SampleRack.Domain.SampleTracking.Entities;

/// <summary>
/// A physical rack storage location (e.g. "A1-02-03"). Codes follow the
/// Zone-Level-Position convention and are the authoritative, operator-assigned
/// identifiers — they are never renamed or regenerated by the system.
/// Occupancy is derived from stored samples and is not held on this aggregate.
/// </summary>
public sealed class RackLocation : AggregateRoot<Guid>, IAuditableEntity
{
    public string Code { get; private set; } = string.Empty;
    public string? Description { get; private set; }

    /// <summary>The rack/bay identifier parsed from the code, e.g. "A1".</summary>
    public string Zone { get; private set; } = string.Empty;

    /// <summary>The storage level (shelf) number, e.g. 2 for "A1-02-03".</summary>
    public int Level { get; private set; }

    /// <summary>The position across a level, e.g. 3 for "A1-02-03".</summary>
    public int Position { get; private set; }

    /// <summary>Deterministic ordering for display and label generation.</summary>
    public int SortOrder { get; private set; }

    /// <summary>Maximum number of samples this location is configured to hold.</summary>
    public int Capacity { get; private set; } = 4;

    public bool IsActive { get; private set; } = true;

    public string CreatedBy { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public string? ModifiedBy { get; set; }
    public DateTime? ModifiedAt { get; set; }

    private RackLocation() { }

    public static RackLocation Create(
        Guid id,
        TenantId tenantId,
        string code,
        string zone,
        int level,
        int position,
        string? description,
        int capacity = 4)
    {
        if (string.IsNullOrWhiteSpace(code))
            throw new DomainException("Rack location code is required.");
        if (string.IsNullOrWhiteSpace(zone))
            throw new DomainException("Rack location zone is required.");
        if (level <= 0)
            throw new DomainException("Rack location level must be a positive number.");
        if (position <= 0)
            throw new DomainException("Rack location position must be a positive number.");

        return new RackLocation
        {
            Id = id,
            TenantId = tenantId,
            Code = code.Trim().ToUpperInvariant(),
            Zone = zone.Trim().ToUpperInvariant(),
            Level = level,
            Position = position,
            Description = description?.Trim(),
            SortOrder = ComputeSortOrder(level, position),
            Capacity = capacity > 0 ? capacity : 4,
            IsActive = true
        };
    }

    public void UpdateDetails(string zone, int level, int position, string? description, int? capacity = null)
    {
        if (string.IsNullOrWhiteSpace(zone))
            throw new DomainException("Rack location zone is required.");
        if (level <= 0)
            throw new DomainException("Rack location level must be a positive number.");
        if (position <= 0)
            throw new DomainException("Rack location position must be a positive number.");

        Zone = zone.Trim().ToUpperInvariant();
        Level = level;
        Position = position;
        Description = description?.Trim();
        SortOrder = ComputeSortOrder(level, position);
        if (capacity is > 0)
            Capacity = capacity.Value;
    }

    /// <summary>
    /// Deactivates the location. The caller (application layer) must first verify
    /// that no active samples remain in the location; this invariant spans
    /// aggregates and cannot be enforced here.
    /// </summary>
    public void Deactivate()
    {
        IsActive = false;
    }

    public void Activate()
    {
        IsActive = true;
    }

    private static int ComputeSortOrder(int level, int position) => (level * 1000) + position;
}
